#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#define D 768
#define H 12
#define HD 64
#define L 12
#define V 50257
#define N 1024
#define FC 3072
#define PL 7087872
float *C,*WE,*PE,*LFB,*LFG;
float *W[L][12];
static float buf[N*FC];
float kc[L][N][3*D],vc[L][N][3*D];
int tlen;
int vt[V][70],vl[V];
char vb[V][70];
int myget(FILE*f,char*s,int m){int c,i=0;while((c=fgetc(f))!=EOF&&c!='\n')if(i<m)s[i++]=c;s[i]=0;return i;}
