 }
}
void enc(char*s,int*out,int*n){
 int i=0,j=0,l=strlen(s);
 while(i<l){
  int best=-1,bl=0;
  for(int v=0;v<V;v++){
   int k;
   for(k=0;k<vl[v]&&i+k<l;k++)if(s[i+k]!=vb[v][k])break;
   if(k==vl[v]&&k>bl){best=v;bl=k;}
  }
  if(best<0){out[j++]=s[i++];}else{out[j++]=best;i+=bl;}
  if(j>=N-22)break;
 }
 *n=j;
}
float*sg(float*o,float*x,float*g,float*b,int n,int D2){
 for(int i=0;i<n;i++){
  float m=0,v=0;
  for(int j=0;j<D2;j++)m+=x[i*D2+j];
  m/=D2;
  for(int j=0;j<D2;j++){float d=x[i*D2+j]-m;v+=d*d;}
  v=sqrtf(v/D2+1e-5f);
  for(int j=0;j<D2;j++)o[i*D2+j]=(x[i*D2+j]-m)/v*g[j]+b[j];
 }
 return o;
}
void mm(float*o,float*x,float*w,float*b,int n,int d,int k){
 for(int i=0;i<n;i++)for(int j=0;j<d;j++){float s=b?b[j]:0;for(int p=0;p<k;p++)s+=x[i*k+p]*w[p*d+j];o[i*d+j]=s;}
}
void attn(int l,float*x,float*x2,int n){
 float qkv[n][3*D];
 mm((float*)qkv,x,W[l][1],W[l][0],n,3*D,D);
 for(int i=0;i<n;i++)for(int j=0;j<3*D;j++){kc[l][i][j]=qkv[i][j];vc[l][i][j]=qkv[i][j];}
 for(int i=0;i<n;i++){
  for(int h=0;h<H;h++){
   float mx=-1e9;
   for(int j=0;j<=i;j++){
    float s=0;
    for(int d=0;d<HD;d++)s+=x2[i*D+h*HD+d]*kc[l][j][h*HD+d];
    mx=mx>s?mx:s;
   }
   float sum=0;
   float prob[1024];
   for(int j=0;j<=i;j++){
    float s=0;
    for(int d=0;d<HD;d++)s+=x2[i*D+h*HD+d]*kc[l][j][h*HD+d];
    float e=expf(s-mx);prob[j]=e;sum+=e;
   }
   for(int j=0;j<=i;j++)prob[j]/=sum;
   for(int d=0;d<HD;d++){float v=0;for(int j=0;j<=i;j++)v+=prob[j]*vc[l][j][h*HD+HD+d];x2[i*D+h*HD+d]=v;}
  }
 }
 mm(x,x2,W[l][3],W[l][2],n,D,D);
}
void mlpf(float*x,float*x2,int n){
 mm(buf,x,W[0][9]?0:0,0,n,FC,D);
 for(int i=0;i<n*FC;i++){float t=buf[i];buf[i]=0.5f*t*(1.f+tanhf(.7978845608f*(t+.044715f*t*t*t)));}
 mm(x2,buf,W[0][11]?0:0,W[0][10],n,D,FC);
}
void layer(int l,float*x,int n){
 float x2[n][D];
 sg((float*)x2,x,W[l][5],W[l][4],n,D);
 attn(l,x,x2,n);
 for(int i=0;i<n*D;i++)x[i]+=x2[i];
 sg((float*)x2,x,W[l][7],W[l][6],n,D);
 mlpf(x,x2,n);
 for(int i=0;i<n*D;i++)x[i]+=x2[i];
}
